svg.script:
var chip = {

  menu: {
    'Value +1': {
      eventName: 'value_incr_1',
      otherEvents: ['dblclick'],
      applicable: (node) => { return true },
      handler: function(evt) {
        chip.increment(this, 1)
      },
    },
    'Value -1': {
      eventName: 'value_decr_1',
      otherEvents: ['dblclick'],
      applicable: (node) => { return true },
      handler: function(evt) {
        chip.increment(this, -1)
      },
    },
    'Stack': {
      eventName: 'chip_stack',
      otherEvents: ['dblclick'],
      applicable: (node) => chip.stack_applicable(node),
      handler: function(evt) {
        chip.stack(this)
      },
    },
  },

  stack_applicable: function(elem) {
    if (elem.getAttribute('data-above') || elem.getAttribute('data-below')) {
      return true
    } else {
      return false
    }
  },

  // Walk a data-above/data-below chain starting at elem, collecting the
  // chip ids found along the way (nearest neighbor first).
  chain: function(elem, attr) {
    const layer = elem.closest('#toys-layer')
    const ids = []
    let nextId = elem.getAttribute(attr)
    while (nextId) {
      const nextEl = layer?.querySelector(`[data-toy-id="${nextId}"]`)
      if (!nextEl) break
      ids.push(nextId)
      nextId = nextEl.getAttribute(attr)
    }
    return ids
  },

  stack: function(elem) {
    const layer = elem.closest('#toys-layer')
    const myId  = elem.getAttribute('data-toy-id')

    // data-above walks toward the base of the pile; data-below walks
    // toward the most recently placed (top) chip.
    const underIds = chip.chain(elem, 'data-above').reverse()
    const aboveIds = chip.chain(elem, 'data-below')

    const ids = [...underIds, myId, ...aboveIds]
    const bottomId = ids[0]
    const bottomEl = layer?.querySelector(`[data-toy-id="${bottomId}"]`) ?? elem

    const { x, y } = chip.anchor_of(bottomEl)

    chip._event('toy:add', {
      toyType: 'stack',
      x, y,
      initArgs: ids,
    })
  },

  // A chip's own placed position (its embedded <svg>'s x/y/width/height
  // are already in the toys-layer's coordinate space, same as any other
  // top-level toy) — its centre point, same convention toys.js's own
  // getAnchor uses for placement.
  anchor_of: function(toyEl) {
    const svg = toyEl.querySelector(':scope > svg')
    const x = parseFloat(svg?.getAttribute('x')) || 0
    const y = parseFloat(svg?.getAttribute('y')) || 0
    const w = parseFloat(svg?.getAttribute('width')) || 0
    const h = parseFloat(svg?.getAttribute('height')) || 0
    return { x: x + w / 2, y: y + h / 2 }
  },

  _event: function(evName, args) {
    const detail = { ...args, retval: {} };
    document.dispatchEvent(new CustomEvent(evName, { detail }));
    if (detail.error) throw new Error(detail.error);
    return detail.retval;
  },

  increment: function(elem, step) {
    const tspan = elem.querySelector('tspan')
    const current = parseInt(tspan.textContent)
    tspan.textContent = String(current + step)
  },

  // Runs once at placement - including during clone (eg, from a supply)
  initialize: function(elem) {
    elem.setAttribute('data-below', '')
    elem.setAttribute('data-above', '')
  },

  on_position_occupied: function(elem, posId, ownerId, movingId) {
    elem.setAttribute('data-below', movingId)
  },

  on_position_vacated: function(elem, posId, ownerId, movingId) {
    elem.setAttribute('data-below', '')
  },

  on_arrive_position: function(elem, posId, ownerId) {
    elem.setAttribute('data-above', ownerId)
  },

  on_depart_position: function(elem, posId, ownerId) {
    elem.setAttribute('data-above', '')
  },

}
